package vn.rtr.aeris.mission;

import java.io.*;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
import vn.rtr.aeris.beta01runtime.NativeSegments;
import vn.rtr.aeris.beta01runtime.Values;

/** One bounded presentation writer. No input/raw/lease operation runs through this lane. */
public final class MissionSnapshot {
    public interface Clock{long now();}
    public interface Listener{void committed(String snapshot,String liveAck);void failed(String reason);}
    private static final class Job{final String value,event,nonce;final Runnable task;Job(String v,String e,String n){value=v;event=e;nonce=n;task=null;}Job(Runnable r){value=null;event=null;nonce=null;task=r;}}
    private final File dir;private final NativeSegments.Sync sync;private final Clock clock;private final Listener listener;private final String processEpoch,source;private final int pid,viewEpoch;private final ArrayDeque<Job> mandatory=new ArrayDeque<>();private Job healthy;private final Thread thread;private boolean closing,failed;private long committedRevision,offeredRevision;private String latest;private RandomAccessFile lockFile;private FileLock lock;
    public MissionSnapshot(File files,NativeSegments.Sync sync,Clock clock,String processEpoch,int pid,int viewEpoch,String source,Listener listener)throws IOException{this.dir=new File(files,"runtime");this.sync=sync;this.clock=clock;this.listener=listener;this.processEpoch=processEpoch;this.pid=pid;this.viewEpoch=viewEpoch;this.source=source;if(processEpoch==null||!processEpoch.matches("[a-f0-9]{32}")||source==null||!source.matches("[a-f0-9]{64}")||pid<=0||viewEpoch<=0)throw new IOException("RUNTIME_LOCAL_IDENTITY");if(!dir.isDirectory()&&!dir.mkdir())throw new IOException("RUNTIME_DIRECTORY");sync.directory(files);if(new File(dir,"current.json.pending").exists()||new File(dir,"response.json.pending").exists())throw new IOException("RUNTIME_PENDING_PREFIX");lockFile=new RandomAccessFile(new File(dir,"writer.lock"),"rw");try{lock=lockFile.getChannel().tryLock();if(lock==null)throw new IOException("RUNTIME_WRITER_ACTIVE");}catch(IOException|RuntimeException e){lockFile.close();throw e;}thread=new Thread(this::run,"aeris-mission-snapshot");thread.start();}
    public synchronized void execute(Runnable work)throws IOException{if(closing||failed||mandatory.size()>=4)throw new IOException("RUNTIME_HANDSHAKE_CAPACITY_OR_CLOSED");mandatory.add(new Job(work));notifyAll();}
    public synchronized void offer(String snapshot,String event,String nonce,boolean required)throws IOException{if(closing||failed)throw new IOException("RUNTIME_WRITER_CLOSED_OR_FAILED");if(snapshot==null||snapshot.getBytes(StandardCharsets.UTF_8).length>131072)throw new IOException("RUNTIME_SNAPSHOT_BYTES");long rev;try{JSONObject o=new JSONObject(snapshot);rev=MissionBootstrap.integer(o,"revision",1,Long.MAX_VALUE);if(!"aeris-mission-snapshot".equals(o.getString("format"))||MissionBootstrap.integer(o,"version",1,1)!=1||!processEpoch.equals(o.getString("processEpoch"))||!source.equals(o.getString("sourceSHA256"))||MissionBootstrap.integer(o,"pid",pid,pid)!=pid||MissionBootstrap.integer(o,"viewEpoch",viewEpoch,viewEpoch)!=viewEpoch||!event.equals(o.getString("event"))||!Objects.equals(nonce,o.isNull("requestNonce")?null:o.getString("requestNonce")))throw new IOException("RUNTIME_SNAPSHOT_BINDING");if(!Arrays.asList("STATUS","READY","TERMINAL","REVIEW").contains(event)||nonce!=null&&!nonce.matches("[a-f0-9]{32}"))throw new IOException("RUNTIME_EVENT_OR_NONCE");}catch(Exception e){throw new IOException("RUNTIME_SNAPSHOT_SCHEMA",e);}if(rev<=offeredRevision)throw new IOException("RUNTIME_OFFER_REGRESSION");Job j=new Job(snapshot,event,nonce);if(required){if(mandatory.size()>=4)throw new IOException("RUNTIME_HANDSHAKE_CAPACITY");healthy=null;mandatory.add(j);}else healthy=j;offeredRevision=rev;notifyAll();}
    public synchronized long committedRevision(){return committedRevision;}
    public synchronized String latest(){return latest;}
    private void run(){try{for(;;){Job j;synchronized(this){while(mandatory.isEmpty()&&healthy==null&&!closing)wait();if(mandatory.isEmpty()&&healthy==null&&closing)break;j=!mandatory.isEmpty()?mandatory.removeFirst():healthy;if(j==healthy)healthy=null;}
        if(j.task!=null){j.task.run();continue;}JSONObject o=new JSONObject(j.value);long rev=MissionBootstrap.integer(o,"revision",1,Long.MAX_VALUE),observed=MissionBootstrap.integer(o,"observedElapsedNs",0,Long.MAX_VALUE);boolean explicit="STATUS".equals(j.event)||"READY".equals(j.event);long received=explicit?MissionBootstrap.integer(o,"requestReceivedElapsedNs",0,observed):-1;long before=clock.now();if(before<observed||explicit&&before-received>10000000000L)throw new IOException("RUNTIME_REQUEST_10S_DEADLINE");synchronized(this){if(rev<=committedRevision)throw new IOException("RUNTIME_REVISION_REGRESSION");}byte[] bytes=j.value.getBytes(StandardCharsets.UTF_8);String name=explicit?"response.json":"current.json";if("READY".equals(j.event)&&!"READY".equals(o.getJSONObject("lifecycle").getString("phase")))throw new IOException("RUNTIME_READY_STATE_REQUIRED");atomic(new File(dir,name),bytes);long done=clock.now();if(done<observed||done<before)throw new IOException("RUNTIME_COMMIT_CLOCK");if(explicit&&done-received>10000000000L)throw new IOException("RUNTIME_REQUEST_10S_DEADLINE");JSONObject ack=new JSONObject().put("format","aeris-mission-live-ack").put("version",1).put("event",j.event).put("requestNonce",j.nonce==null?JSONObject.NULL:j.nonce).put("requestReceivedElapsedNs",explicit?received:JSONObject.NULL).put("processEpoch",o.getString("processEpoch")).put("viewEpoch",viewEpoch).put("pid",pid).put("revision",rev).put("sourceSHA256",o.getString("sourceSHA256")).put("context",o.get("context")).put("snapshotPath","files/runtime/"+name).put("snapshotSHA256",Values.hash(bytes)).put("committedElapsedNs",done).put("ackElapsedNs",clock.now()).put("phase",o.getJSONObject("lifecycle").getString("phase"));long ackAt=ack.getLong("ackElapsedNs");if(ackAt<done||explicit&&ackAt-received>10000000000L)throw new IOException("RUNTIME_ACK_CLOCK_OR_10S_DEADLINE");synchronized(this){committedRevision=rev;latest=j.value;}listener.committed(j.value,ack.toString());
    }}catch(Exception e){synchronized(this){failed=true;mandatory.clear();healthy=null;}listener.failed(e.getClass().getSimpleName()+":"+e.getMessage());}finally{try{if(lock!=null)lock.release();if(lockFile!=null)lockFile.close();}catch(Exception e){listener.failed("RUNTIME_LOCK_CLOSE:"+e.getMessage());}}}
    private void atomic(File target,byte[] b)throws IOException{File p=new File(dir,target.getName()+".pending");if(p.exists())throw new IOException("RUNTIME_UNCERTAIN_PREFIX");try(FileOutputStream out=new FileOutputStream(p)){out.write(b);sync.file(out.getFD());}if(!p.renameTo(target))throw new IOException("RUNTIME_RENAME");sync.directory(dir);}
    public synchronized void shutdown(){closing=true;healthy=null;notifyAll();}
    public boolean await(long millis)throws InterruptedException{if(millis<=0)return!thread.isAlive();thread.join(Math.min(5000,millis));return!thread.isAlive();}
}
